"""Specific first-grade Language and Communication sequences."""
from __future__ import annotations


def _s(title: str, goal: str, example: str) -> tuple[str, str, str]:
    return title, goal, example


ATTITUDES = (
    ("de Actitud LE01 OAA A", "interés activo y disfrute de la lectura"),
    ("de Actitud LE01 OAA B", "disposición para compartir ideas, experiencias y opiniones"),
    ("de Actitud LE01 OAA C", "expresión creativa oral y escrita"),
    ("de Actitud LE01 OAA D", "trabajo riguroso y perseverante según el propósito"),
    ("de Actitud LE01 OAA E", "reflexión sobre las propias ideas e intereses"),
    ("de Actitud LE01 OAA F", "empatía con personas y contextos diversos"),
    ("de Actitud LE01 OAA G", "respeto por opiniones distintas y valoración del diálogo"),
)


def attitude_link(oa_number: int, lesson_index: int, goal: str) -> dict[str, str]:
    code, attitude = ATTITUDES[(oa_number + lesson_index * 2) % len(ATTITUDES)]
    return {"code": code, "type": "Actitud", "application": f"Se promueve {attitude}. La evidencia se recoge durante la meta estudiantil «{goal}», sin calificar rasgos personales."}


