def build_language_sequence(code: str) -> dict | None:
    data = SEQUENCES.get(code)
    if not data:
        return None
    oa_number = int(code.rsplit(" ", 1)[-1])
    source = f"https://www.curriculumnacional.cl/curriculum/1o-6o-basico/lenguaje-comunicacion/1-basico/le01-oa-{oa_number:02d}"
    lessons = []
    for index, (title, goal, example) in enumerate(data["steps"]):
        lessons.append({
            "title": title,
            "purpose": f"Construir {data['topic'].lower()} mediante «{title.lower()}», haciendo visible cómo el lenguaje produce y comunica significado.",
            "goal": f"Hoy {goal}.",
            "opening": f"Presenta dos respuestas o textos breves relacionados con «{title.lower()}»: uno ayuda a comprender y otro contiene el problema «{data['misconception']}». Cada estudiante elige y explica una primera pista antes del modelado.",
            "model": example,
            "guided": f"Resuelven un caso semejante por turnos: primero señalan una pista oral, escrita o visual; después explican la decisión vinculada a la meta «{goal}». El docente retroalimenta significado y estrategia, no rapidez.",
            "independent": f"Cada estudiante produce una evidencia nueva de «{goal}» sin copiar el ejemplo. Puede leer, escribir, dibujar con rótulos o responder oralmente cuando esa vía conserva la demanda del OA.",
            "ticket": f"Ante un caso breve distinto, presenta una evidencia para la meta «{goal}»; señala la pista usada y revisa una decisión después de releer o escuchar nuevamente.",
            "materials": data["materials"],
            "support": "Anticipa vocabulario, reduce la extensión del texto sin cambiar su complejidad central, ofrece lectura compartida o dictado al adulto cuando corresponda y retira una ayuda a la vez.",
            "extension": f"Cambia destinatario, género, palabra, orden o punto de vista y explica cómo esa modificación afecta «{data['topic'].lower()}». Exige una decisión nueva, no más cantidad de lo mismo.",
            "evidence": f"Producción individual vinculada a «{goal}», acompañada por la pista textual, sonora, visual o comunicativa que sostuvo la decisión.",
            "criteria": ["comunica o comprende una idea pertinente al OA", "usa una pista específica del lenguaje oral, escrito o visual", "explica o revisa una decisión con propósito"],
            "next_step": "Avanza si la evidencia conserva significado y usa una pista pertinente; ante un patrón de error, forma un grupo breve para modelar otra vía y recoge una nueva evidencia individual.",
            "short_version": "Conserva el contraste inicial, el ejemplo específico, una práctica guiada, la producción individual y el ticket. Reduce cantidad o turnos, no la comprensión, producción ni revisión.",
            "home_task": "Comparte en casa un texto, palabra o intervención breve relacionada con la meta; registra qué comprendió la otra persona o qué cambiaste para comunicar mejor. No requiere internet ni impresión.",
            "complementary": ["Recuperación: vuelve a un ejemplo oral o visual, modela una sola pista y permite un nuevo intento con menor extensión.", "Taller de errores: compara dos respuestas ficticias, localiza qué ayuda al significado y mejora solo una decisión.", "Profundización: transforma destinatario, punto de vista o género y justifica el efecto en el mensaje."],
            "difficulty_actions": [
                {"signal": "No inicia o dice que no sabe", "action": "Ofrece dos opciones de entrada, relee o vuelve a decir la consigna y modela un ejemplo diferente.", "check": "Inicia una respuesta propia y puede señalar qué debe averiguar o comunicar."},
                {"signal": data["misconception"].capitalize(), "action": "Detén la respuesta, vuelve a una pista precisa del texto, sonido, imagen o situación y piensa en voz alta.", "check": "Corrige un caso nuevo explicando la pista, no solo cambiando la respuesta."},
                {"signal": "Responde, pero no puede justificar", "action": "Pregunta dónde lo vio, oyó o decidió y ofrece una frase de apoyo que luego se retira.", "check": "Vincula la respuesta con una evidencia pertinente en un segundo caso."},
            ],
            "specialist_coordination": "El docente conduce comprensión y producción; educación diferencial o fonoaudiología, cuando corresponda al plan del estudiante, asesora acceso y comunicación sin reemplazar la enseñanza, convertir variaciones lingüísticas en déficit ni diagnosticar durante la clase.",
            "transversal": [attitude_link(oa_number, index, goal)],
        })
    return {
        "topic": data["topic"],
        "pedagogical_explanation": data["explanation"],
        "prerequisites": data["prerequisites"],
        "vocabulary": data["vocabulary"],
        "official_alignment": {
            "units": ["Progresión anual de Lenguaje y Comunicación de 1° básico"],
            "indicators": [f"Criterio interno derivado del OA: {goal}." for _, goal, _ in data["steps"][:3]],
            "source": source,
            "indicator_origin": "criterios internos derivados del OA; requieren contraste con el Programa de Estudio",
        },
        "lessons": lessons,
    }
